<?php
namespace App\Http\Controllers;
use App\Models\Customer;use App\Models\Organization;use App\Models\TireProduct;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Artisan;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class SuperAdminDummyDataController extends Controller{
 public function index():View{$organizations=Organization::withCount(['customers'=>fn($q)=>$q->where(fn($x)=>$x->where('notes','like','[DUMMY]%')->orWhere('notes','like','[DEMO-BULK]%')),'vehicles','tireSets'])->orderBy('name')->get();return view('superadmin.dummy-data',compact('organizations'));}
 public function generate(Request$request):RedirectResponse{$data=$request->validate(['organization_id'=>['required','integer','exists:organizations,id'],'sets'=>['required','integer','between:50,2000'],'confirmed'=>['accepted']]);$org=Organization::findOrFail($data['organization_id']);if(!$org->branches()->where('active',true)->exists())return back()->withErrors(['organization_id'=>'Miljøet mangler en aktiv avdeling.'])->withInput();set_time_limit(300);$exit=Artisan::call('demo:scale-inventory',['--organization'=>$org->id,'--sets'=>$data['sets']]);if($exit!==0)return back()->withErrors(['dummy'=>'Dummydata kunne ikke opprettes. Ingen ekte data skal være slettet.']);DB::table('audit_logs')->insert(['organization_id'=>$org->id,'user_id'=>$request->user()->id,'action'=>'superadmin.dummy.generated','subject_type'=>Organization::class,'subject_id'=>$org->id,'ip_address'=>$request->ip(),'metadata'=>json_encode(['sets'=>$data['sets']]),'created_at'=>now()]);return back()->with('success',$org->name.' er fylt med opptil '.$data['sets'].' syntetiske biler og tilhørende hjulsett.');}
 public function delete(Request$request):RedirectResponse{$data=$request->validate(['organization_id'=>['required','integer','exists:organizations,id'],'confirmed'=>['accepted']]);$org=Organization::findOrFail($data['organization_id']);$ids=Customer::where('organization_id',$org->id)->where(fn($q)=>$q->where('notes','like','[DUMMY]%')->orWhere('notes','like','[DEMO-BULK]%'))->pluck('id');$products=0;DB::transaction(function()use($ids,$org,$request,&$products){Customer::withTrashed()->whereIn('id',$ids)->forceDelete();$products=TireProduct::withTrashed()->where('organization_id',$org->id)->where('sku','like','DEMO-%')->forceDelete();DB::table('audit_logs')->insert(['organization_id'=>$org->id,'user_id'=>$request->user()->id,'action'=>'superadmin.dummy.deleted','subject_type'=>Organization::class,'subject_id'=>$org->id,'ip_address'=>$request->ip(),'metadata'=>json_encode(['customers'=>$ids->count(),'products'=>$products]),'created_at'=>now()]);});return back()->with('success',$ids->count().' merkede dummy-kunder og '.$products.' dummyprodukter ble slettet fra '.$org->name.'. Ekte data ble ikke berørt.');}
}
